package managedbrowser

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// This fixture is generated by the actual extension bridge. Its backend and
// native acknowledgements are explicitly simulated; the tests below exercise
// the production Go parser, original calls and lifecycle over real WebSockets.
func newWorkerRecoveryFixture(t *testing.T, mutate func(map[string]any)) *recoveryFixture {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("..", "managedviewer", "testdata", "worker-recovery-fixture.json"))
	if err != nil {
		t.Fatal(err)
	}
	var wire map[string]json.RawMessage
	if err := json.Unmarshal(data, &wire); err != nil {
		t.Fatal(err)
	}
	f := newRecoveryFixture(t, func(f *recoveryFixture) {
		if err := json.Unmarshal(wire["oldOpen"], &f.old.identity); err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(wire["recoveredOpen"], &f.next.identity); err != nil {
			t.Fatal(err)
		}
		f.next.contextUID = "replacement-context"
		f.old.intercept = func(peer *userFixture, request userTestRequest) bool {
			switch request.Operation {
			case "open":
				peer.evaluated(request, wire["oldOpen"])
				return true
			case "select":
				peer.evaluated(request, wire["oldSelect"])
				return true
			case "retire":
				return true // A stopped execution cannot invent Page cleanup.
			}
			return false
		}
		f.next.intercept = func(peer *userFixture, request userTestRequest) bool {
			switch request.Operation {
			case "open":
				var recovery managedWorkerRecoveryRequest
				if err := json.Unmarshal(request.Arguments["recovery"], &recovery); err != nil {
					t.Error(err)
					return true
				}
				var expected managedWorkerRecoveryRequest
				_ = json.Unmarshal(wire["recovery"], &expected)
				expected.Nonce = recovery.Nonce
				if recovery != expected || !workerRecordText(recovery.Nonce) {
					t.Errorf("unbound replacement admission: %+v", recovery)
				}
				var response map[string]any
				_ = json.Unmarshal(wire["recoveredOpen"], &response)
				response["workerRecovery"].(map[string]any)["nonce"] = recovery.Nonce
				if mutate != nil {
					mutate(response)
				}
				peer.evaluated(request, response)
				return true
			case "status":
				peer.evaluated(request, wire["status"])
				return true
			case "retire":
				peer.evaluated(request, wire["disconnect"])
				return true
			}
			return false
		}
	})
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if _, err := f.previous.Command(ctx, json.RawMessage(`{"operation":"select","tabId":7,"deliveryId":"delivery-original"}`)); err != nil {
		t.Fatal(err)
	}
	f.previous.mu.Lock()
	if f.previous.viewStatus == nil || f.previous.viewStatus.LeaseID != "view-original" || f.previous.humanRisk {
		t.Fatal("original active read-only view was not retained")
	}
	f.previous.mu.Unlock()
	return f
}

func endOriginalWorker(t *testing.T, f *recoveryFixture) {
	t.Helper()
	f.old.write(map[string]any{"method": "Runtime.executionContextDestroyed", "sessionId": "worker-session", "params": map[string]any{"executionContextId": f.old.contextID, "executionContextUniqueId": f.old.contextUID}})
	userWait(t, f.previous.Done())
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if err := f.previous.Close(ctx); err != nil {
		t.Fatal(err)
	}
}

func TestManagedWorkerRecoveryConsumesActualBridgeWireWithReusedTarget(t *testing.T) {
	f := newWorkerRecoveryFixture(t, nil)
	endOriginalWorker(t, f)
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()
	next, err := f.s.Recover(ctx, f.previous)
	if err != nil {
		t.Fatal(err)
	}
	if next == f.previous || next.targetID != f.previous.targetID || next.contextUID == f.previous.contextUID || next.identity.WorkerBootID == f.previous.identity.WorkerBootID {
		t.Fatal("replacement confused target identity with execution identity")
	}
	if f.s.Info().BrowserPID != 10 || f.s.Info().RunID != f.old.identity.RunID || f.bindCalls != 1 {
		t.Fatal("replacement changed or replayed the original Browser binding")
	}
	old, current := f.s.nativeConnections[0], f.s.currentNative
	var retirement struct {
		TransportRetired, CleanupConfirmed bool
		CleanupProof                       string
	}
	if old.record.ExecutionEnd == nil || old.record.ControllerCleanup == nil || json.Unmarshal(old.record.ControllerCleanup.Result, &retirement) != nil || !retirement.TransportRetired || retirement.CleanupConfirmed || retirement.CleanupProof != "worker-execution-ended" {
		t.Fatal("execution end was confused with native resource cleanup")
	}
	if current.record.WorkerRecovery == nil || current.record.RecoveryState == nil || current.record.RecoveryState.WorkerEpoch != 2 || current.record.Worker == nil || current.record.Worker.ContextUID != "replacement-context" {
		t.Fatal("new generation proof was not persisted")
	}
	var receipt managedWorkerRecoveryReceipt
	if json.Unmarshal(current.record.WorkerRecovery.Result, &receipt) != nil || len(receipt.RetiredViews) != 1 || receipt.RetiredViews[0].LeaseID != "view-original" || !receipt.RetiredViews[0].StopAcknowledged || !receipt.RetiredViews[0].DetachAcknowledged {
		t.Fatal("original view release acknowledgements lost")
	}
	if _, err := f.previous.Command(ctx, json.RawMessage(`{"operation":"status"}`)); err == nil {
		t.Fatal("old authority revived")
	}
}

func TestManagedWorkerRecoveryRejectsIncompleteOrUnboundResourceProof(t *testing.T) {
	for _, name := range []string{"missing-journal", "journal", "incarnation", "epoch", "nonce", "old-boot", "new-boot", "from-epoch", "to-epoch", "risk", "paused", "missing-view", "wrong-lease", "missing-target", "stop", "detach", "duplicate-view", "extra-field", "not-clean"} {
		t.Run(name, func(t *testing.T) {
			f := newWorkerRecoveryFixture(t, func(response map[string]any) {
				state := response["recoveryState"].(map[string]any)
				proof := response["workerRecovery"].(map[string]any)
				view := proof["retiredViews"].([]any)[0].(map[string]any)
				switch name {
				case "missing-journal":
					delete(response, "recoveryState")
				case "journal":
					state["journalId"] = "fresh-empty-journal"
				case "incarnation":
					state["browserIncarnation"] = "another-browser"
				case "epoch":
					state["workerEpoch"] = 3
				case "nonce":
					proof["nonce"] = "old-challenge"
				case "old-boot":
					proof["previousWorkerBootId"] = "another-worker"
				case "new-boot":
					proof["workerBootId"] = "another-worker"
				case "from-epoch":
					proof["fromWorkerEpoch"] = 0
				case "to-epoch":
					proof["toWorkerEpoch"] = 3
				case "risk":
					proof["inputRiskClear"] = false
				case "paused":
					proof["paused"] = false
				case "missing-view":
					proof["retiredViews"] = []any{}
				case "wrong-lease":
					view["leaseId"] = "old-other-view"
				case "missing-target":
					delete(view, "targetId")
				case "stop":
					view["stopAcknowledged"] = false
				case "detach":
					view["detachAcknowledged"] = false
				case "duplicate-view":
					proof["retiredViews"] = []any{view, view}
				case "extra-field":
					proof["cleanupConfirmed"] = true
				case "not-clean":
					response["status"].(map[string]any)["cleanupPending"] = 1
				}
			})
			endOriginalWorker(t, f)
			ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
			defer cancel()
			if controller, err := f.s.Recover(ctx, f.previous); err == nil || controller != nil {
				t.Fatal("unconfirmed replacement was published")
			}
			if f.s.Info().SocketPath != "" || f.s.RecoveryStatus().State != "degraded" || len(f.s.controllers) != 2 || len(f.s.nativeConnections) != 2 || f.bindCalls != 1 {
				t.Fatal("failed submitted resources were lost or exposed")
			}
			if _, err := f.s.Recover(ctx, f.previous); err == nil || f.bindCalls != 1 {
				t.Fatal("unknown open was replayed")
			}
		})
	}
}

func TestManagedWorkerRecoveryRejectsUnchangedContextEvenWithNewBoot(t *testing.T) {
	f := newWorkerRecoveryFixture(t, nil)
	f.next.contextUID = f.old.contextUID
	endOriginalWorker(t, f)
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if _, err := f.s.Recover(ctx, f.previous); err == nil {
		t.Fatal("new boot string authorized the old execution context")
	}
	f.next.mu.Lock()
	defer f.next.mu.Unlock()
	for _, r := range f.next.requests {
		if r.Operation == "open" {
			t.Fatal("replacement open submitted before exact execution identity changed")
		}
	}
}

func TestManagedWorkerExecutionEndPersistsAfterNativeDegradation(t *testing.T) {
	f := newWorkerRecoveryFixture(t, nil)
	// The original native exit may be observed first; the later original CDP
	// event still has to be persisted rather than lost by the ready-state gate.
	f.s.recovery.State = "degraded"
	endOriginalWorker(t, f)
	data, err := os.ReadFile(filepath.Join(f.s.info.RunDir, "lifecycle.json"))
	if err != nil {
		t.Fatal(err)
	}
	var saved lifecycle
	if err := json.Unmarshal(data, &saved); err != nil {
		t.Fatal(err)
	}
	if len(saved.NativeConnections) != 1 || saved.NativeConnections[0].ExecutionEnd == nil || saved.NativeConnections[0].ExecutionEnd.ContextUID != f.old.contextUID || saved.NativeConnections[0].ExecutionEnd.Method != "Runtime.executionContextDestroyed" {
		t.Fatal("late exact original execution witness was not saved")
	}
}

func TestManagedSameWorkerRecoveryRejectsFreshJournal(t *testing.T) {
	f := newRecoveryFixture(t)
	f.next.intercept = func(peer *userFixture, r userTestRequest) bool {
		if r.Operation != "open" {
			return false
		}
		data, _ := json.Marshal(peer.identity)
		var response map[string]any
		_ = json.Unmarshal(data, &response)
		response["status"] = peer.status()
		response["recoveryState"] = map[string]any{"version": 1, "browserIncarnation": "original-browser-incarnation", "journalId": "fresh-empty-journal", "workerEpoch": 1}
		peer.evaluated(r, response)
		return true
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if _, err := f.s.Recover(ctx, f.previous); err == nil || !strings.Contains(err.Error(), "journal") {
		t.Fatalf("same worker lost original journal: %v", err)
	}
}
